'use client';

import { useEffect, useRef, useState } from 'react';
import gsap from 'gsap';
import styles from './surprise.module.css';
import { surpriseContent } from './content';

type Stage = 'boot' | 'ready' | 'question' | 'success';

export default function SurpriseExperience() {
  const [stage, setStage] = useState<Stage>('boot');
  const [progress, setProgress] = useState(0);
  const [checks, setChecks] = useState(0);
  const [choice, setChoice] = useState<string | null>(null);
  const sceneRef = useRef<HTMLElement>(null);

  useEffect(() => {
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const timers: number[] = [];
    const later = (callback: () => void, delay: number) => {
      timers.push(window.setTimeout(callback, reducedMotion ? 0 : delay));
    };

    [25, 50, 75, 100].forEach((value, index) => {
      later(() => setProgress(value), 500 + index * 450);
      if (index < surpriseContent.bootChecks.length) {
        later(() => setChecks(index + 1), 850 + index * 450);
      }
    });
    later(() => setStage('ready'), reducedMotion ? 0 : 3100);

    return () => timers.forEach(window.clearTimeout);
  }, []);

  useEffect(() => {
    if (stage === 'boot') return;
    const scene = sceneRef.current;
    if (!scene || window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;

    const panel = scene.querySelector<HTMLElement>(`.${styles.panel}`);
    if (panel) {
      gsap.fromTo(
        panel,
        { opacity: 0, y: 22, filter: 'blur(5px)' },
        { opacity: 1, y: 0, filter: 'blur(0px)', duration: 0.8, ease: 'power3.out' },
      );
    }
  }, [stage]);

  const begin = () => setStage('question');

  const choose = (answer: string) => {
    setChoice(answer);
    const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    window.setTimeout(() => setStage('success'), reducedMotion ? 0 : 650);
  };

  return (
    <main className={styles.experience} ref={sceneRef}>
      <div className={styles.ambient} aria-hidden="true">
        <span className={styles.orb} />
        <span className={styles.petalOne}>✿</span>
        <span className={styles.petalTwo}>✿</span>
        <span className={styles.petalThree}>✿</span>
      </div>

      <header className={styles.topline}>
        <span>{surpriseContent.experienceName}</span>
        <span className={styles.online}><i /> PRIVATE SESSION</span>
      </header>

      {stage === 'boot' ? (
        <section className={`${styles.panel} ${styles.boot}`} aria-live="polite">
          <div className={styles.seal} aria-hidden="true"><span>✳</span></div>
          <p className={styles.kicker}>A little story, made just for you</p>
          <h1 className={styles.name}>{surpriseContent.name.split('').join(' ')}</h1>
          <p className={styles.bootLabel}>SYSTEM INITIALIZING<span className={styles.cursor}>_</span></p>

          <div className={styles.progressMeta}>
            <span>LOADING OUR STORY</span><span>{String(progress).padStart(3, '0')}%</span>
          </div>
          <div className={styles.progressTrack} role="progressbar" aria-label="Loading our story" aria-valuemin={0} aria-valuemax={100} aria-valuenow={progress}>
            <span style={{ width: `${progress}%` }} />
          </div>

          <ul className={styles.checks}>
            {surpriseContent.bootChecks.map((check, index) => (
              <li className={index < checks ? styles.checkVisible : ''} key={check}>
                <span aria-hidden="true">✓</span>{check}
              </li>
            ))}
          </ul>

          <div className={`${styles.dependency} ${progress === 100 ? styles.dependencyVisible : ''}`}>
            <span className={styles.warning}>✳</span>
            <span>One critical dependency found...</span>
            <strong>{surpriseContent.criticalDependency}</strong>
          </div>
        </section>
      ) : stage === 'ready' ? (
        <section className={`${styles.panel} ${styles.ready}`}>
          <div className={styles.readyGlyph} aria-hidden="true">♡</div>
          <p className={styles.kicker}>All the important things are here</p>
          <h1>Before we continue,<br />I need to verify one thing.</h1>
          <p className={styles.signature}>With all my love, <span>{surpriseContent.signature}</span></p>
          <button className={styles.primaryButton} onClick={begin}>
            <span>BEGIN</span><span aria-hidden="true">↗</span>
          </button>
          <p className={styles.microcopy}>A small trip down memory lane</p>
        </section>
      ) : stage === 'question' ? (
        <section className={`${styles.panel} ${styles.memory}`}>
          <div className={styles.memoryTopline}><span>MEMORY 01</span><span>01 <i /> 04</span></div>
          <div className={styles.memoryOrnament} aria-hidden="true"><span>✳</span></div>
          <p className={styles.kicker}>A moment I keep close</p>
          <h1>{surpriseContent.firstMemory.title}</h1>
          <p className={styles.question}>{surpriseContent.firstMemory.question}</p>
          <div className={styles.answers} role="group" aria-label="Choose who said I love you first">
            {surpriseContent.firstMemory.choices.map((answer, index) => (
              <button
                className={`${styles.answer} ${choice === answer ? styles.answerSelected : ''}`}
                key={answer}
                onClick={() => choose(answer)}
                type="button"
              >
                <span className={styles.answerIndex}>0{index + 1}</span>
                <span>{answer}</span>
                <span className={styles.answerArrow} aria-hidden="true">↗</span>
              </button>
            ))}
          </div>
          <p className={styles.microcopy}>Take your time, my love.</p>
        </section>
      ) : (
        <section className={`${styles.panel} ${styles.success}`} aria-live="polite">
          <div className={styles.memoryTopline}><span>MEMORY 01</span><span>FOUND <i>♡</i></span></div>
          <div className={styles.heartBloom} aria-hidden="true">
            <span className={styles.heart}>♥</span>
            <i>✿</i><i>✧</i><i>✿</i><i>✧</i><i>·</i><i>·</i>
          </div>
          <p className={styles.kicker}>Some things never leave us</p>
          <h1>The words were only<br />the beginning.</h1>
          <p className={styles.memoryMessage}>{surpriseContent.firstMemory.message}</p>
          {choice && <p className={styles.chosenAnswer}>YOU CHOSE <span>{choice}</span></p>}
          <div className={styles.signatureRule} />
          <p className={styles.signature}>Always yours, <span>{surpriseContent.signature}</span></p>
          <p className={styles.comingSoon}>MORE MEMORIES WAIT AHEAD <span>···</span></p>
        </section>
      )}

      <footer className={styles.footer}>
        <span>BUILT WITH LOVE</span><span>01 / ∞</span>
      </footer>
    </main>
  );
}
